action.command:
cd /workspace/project && python3 - <<'PY'
import json,datetime
d=json.load(open('/tmp/open.json'))
for it in d['items']:
    dl=it.get('deadline') or ''
    rew=it.get('rewardAmount') or it.get('potUsd')
    fee=it.get('entryFeeUsd')
    print(f"\n### {it['slug']}")
    print(f"  judul    : {it['title'][:95]}")
    print(f"  hadiah   : {rew} | fee masuk: {fee} | pot: {it.get('potUsd')}")
    print(f"  deadline : {dl[:19]} | entri: {it.get('submissionCount')} | kategori: {it.get('category')}")
    pg=it.get('prizeGate'); 
    if pg: print(f"  prizeGate: {json.dumps(pg)[:110]}")
    r=it.get('rewards'); 
    if r: print(f"  rewards  : {json.dumps(r)[:160]}")
PY

